("style");k.textContent=`
  @keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }
  
  /* Focus styles */
  input:focus {
    border-color: #3498db;
    outline: none;
    box-shadow: 0 0 0 3px rgba(52, 152, 219, 0.2);
  }
  
  button:not(:disabled):hover {
    opacity: 0.9;
  }
  
  button[type="button"]:hover {
    text-decoration: underline;
  }
  
  /* Responsive */
  @media (max-width: 768px) {
    .login-form,
    .recovery-modal {
      padding: 30px 20px;
    }
    
    .form-container {
      padding: 10px;
    }
    
    .logo img {
      width: 100px;
      height: 100px;
    }
    
    h1 {
      font-size: 1.6rem;
    }
    
    .subtitle {
      font-size: 1rem;
      margin-bottom: 1.5rem;
    }
  }
  
  @media (max-width: 480px) {
    .login-form,
    .recovery-modal {
      padding: 25px 15px;
    }
    
    .recovery-title {
      font-size: 1.5rem;
    }
    
    .recovery-subtitle {
      font-size: 1.1rem;
    }
  }
`;document.head.appendChild(k);export{J as default};
